/**
 * Batik ornament record (mirrored in docs/BATIK_ASSETS.md).
 *
 * One motif family is used across the whole site: kawung. Every file in
 * public/ornament/ is generated by scripts/build-batik.py from one geometry.
 *
 * Why kawung, and why not parang:
 *  - mangkunegaran.id's article "Motif Batik Mangkunegaran" (13 Aug 2024)
 *    says that inside Pura Mangkunegaran, parang is still a *larangan* motif
 *    reserved for the core Mangkunegaran family; the official reservation
 *    page also asks visitors not to wear parang/lereng batik. Using parang as
 *    this unofficial site's decoration would ignore that protocol.
 *  - The motifs that article names as Mangkunegaran creations (Buketan
 *    Pakis, Sapanti Nata, Wahyu Tumurun, Parang Kesit Barong, Parang Sondhen,
 *    Parang Klithik Glebag Seruni, Liris Cemeng, Buketan Paris) have no
 *    openly licensed vector or reference image we could verify.
 *  - Truntum was considered and not used: popular accounts attribute it to the
 *    Kasunanan court (not verified here), and the site must not mix the two
 *    courts' symbols.
 *  - Kawung is a classical Javanese motif documented in a dated museum sample
 *    and available as a CC0 vector. It is NOT presented as a Mangkunegaran
 *    motif or as carrying any royal meaning.
 */
import { z } from "zod";
import { parseAll } from "./schema";

const ornamentSchema = z.object({
  id: z.string(),
  file: z.string(),
  motif: z.string(),
  use: z.string(),
  origin: z.enum(["sourced", "adapted", "original"]),
  sources: z
    .array(
      z.object({
        role: z.enum(["base-vector", "reference"]),
        title: z.string(),
        url: z.url(),
        creator: z.string(),
        institution: z.string().optional(),
        date: z.string().optional(),
        license: z.string(),
        licenseUrl: z.url().optional(),
        attributionRequired: z.boolean(),
      }),
    )
    .min(1),
  modifications: z.string(),
  attribution: z.string(),
  accessed: z.string(),
});
export type Ornament = z.infer<typeof ornamentSchema>;

const BASE = {
  role: "base-vector" as const,
  title: "Ragam Hias Jawa - Kawung (Polos).svg",
  url: "https://commons.wikimedia.org/wiki/File:Ragam_Hias_Jawa_-_Kawung_(Polos).svg",
  creator: "Pinerineks (Wikimedia Commons user), own work, 2020-10-14",
  license: "CC0 1.0",
  licenseUrl: "https://creativecommons.org/publicdomain/zero/1.0/",
  attributionRequired: false,
};
const REFERENCE = {
  role: "reference" as const,
  title: "Batikpatroon 'Kawung picis' (RV-847-85)",
  url: "https://commons.wikimedia.org/wiki/File:Collectie_NMvWereldculturen,_RV-847-85,_Batikpatroon,_%27Kawung_picis%27,_voor_1891.jpg",
  creator: "Unknown batik maker",
  institution: "Nationaal Museum van Wereldculturen (Wereldmuseum), Netherlands",
  date: "before 1891",
  license: "Public domain (photograph as published on Wikimedia Commons)",
  attributionRequired: false,
};
const MODS =
  "Redrawn from the CC0 geometry as a 48-unit tile; leaves made rounder, two focal dots added to each leaf and leaf tips trimmed so a small lozenge stays open where four leaves meet, following the museum's description of RV-847-85. An adaptation, not a reproduction of the sample.";
const ATTRIBUTION =
  "Kawung ornament adapted by Kelompok 7 from a CC0 vector by Pinerineks (Wikimedia Commons), with reference to NMvW RV-847-85 'Kawung picis' (before 1891).";

export const ORNAMENTS = parseAll(
  ornamentSchema,
  [
    { id: "kawung-tile", file: "public/ornament/kawung-tile.svg", motif: "Kawung", use: "Repeating field in page heroes (masked, low contrast)", origin: "adapted", sources: [BASE, REFERENCE], modifications: MODS, attribution: ATTRIBUTION, accessed: "2026-10-21" },
    { id: "kawung-border", file: "public/ornament/kawung-border.svg", motif: "Kawung", use: "Thin border where a hero meets the paper content", origin: "adapted", sources: [BASE, REFERENCE], modifications: `${MODS} One half-row of the tile, cut as a strip.`, attribution: ATTRIBUTION, accessed: "2026-10-21" },
    { id: "kawung-flower", file: "public/ornament/kawung-flower.svg", motif: "Kawung (single flower of four leaves)", use: "Section and period markers on dividers", origin: "adapted", sources: [BASE, REFERENCE], modifications: `${MODS} A single four-leaf group.`, attribution: ATTRIBUTION, accessed: "2026-10-21" },
  ],
  "ornaments",
);
